using UnityEngine; public class GhostFinder : MonoBehaviour { void Start() { InvokeRepeating("Check", 1f, 1f); } void Check() { var dm = WordsOnTheWaves.Gameplay.DecorManager.Instance; if (dm == null) return; Debug.Log($"isActive: {dm.isActive}, allSlots count: {dm.GetType().GetField("allSlots", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)?.GetValue(dm)}"); } }
